 x.binding.encounterInputs={candidateRoutineItemId:x.candidateRoutineItemId,selectedManualReportIds:x.selectedManualReportIds,use:x.requestedUse};
 x.binding.scanId=p.scanId;x.binding.captureSessionId=p.captureSessionId;x.binding.partOneGeneration=p.generation;x.binding.partOneRevision=p.evidenceRevision;x.binding.partTwoRevision=p.resultRevision;x.binding.partTwoBindingKey=p.bindingKey;
