 if(p.output.kind==='bound'){const d=p.output.productFacts.binding;if(d.kind!=='declaration')throw Error('Fixture declaration');x.binding.subject={kind:'declaration',itemId:d.itemId,snapshotId:d.snapshotId,declarationId:d.declarationId,declarationRevision:d.declarationRevision,productId:null,variantId:null,formulaVersionId:null,packageScope:d.packageConfirmation==='unconfirmed'?'published_version':'confirmed_package'};}
