export function evidence(x:PersonalEvaluationInput,p:NormalizationInput){x.partTwo=normalize(p,LOCAL_DICTIONARY_RELEASE,p2metadata);return align(x);}
export function comparator(x=baseInput(),intent:PersonalEvaluationInput['binding']['intent']='replace') {
 const item=p3routine(A.item);x.context.routine=p3revision(A.routine,{completeness:'partial',items:[item]});const assessment=p3assessment(item);assessment.id=A.assessmentRecord;x.context.assessments=[p3revision(A.assessment,assessment)];x.binding.comparatorId=item.id;x.binding.intent=intent;return align(x);
}
export function keepInput(){const x=comparator();x.binding.comparatorId=null;x.binding.intent='check_current';x.candidateRoutineItemId=A.item;x.context.profile!.data.primaryGoal={state:'known',value:'maintain'};return align(x);}
export function avoid(x:PersonalEvaluationInput,unresolved=false){const data:ConfirmedPreference={id:A.prefRecord,revision:1,kind:'avoid_ingredient',target:{kind:'ingredient',identity:unresolved?{kind:'unresolved',originalTerm:'My unresolved term'}:{kind:'resolved',ingredientId:'glycerin'}},strength:'decisive',status:'confirmed',confirmedAt:x.now,source:{kind:'structured'}};x.context.preferences=[p3revision(A.pref,data)];return align(x);}
